func (os HouseholdInvitationSlice) LoadAcceptedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.AcceptedByMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AcceptedByMember = nil
		o.R.Loaded.AcceptedByMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	householdInvitationByKey := make(map[uuid.UUID][]*HouseholdInvitation, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		// NULL never matches any row in SQL, so don't add it to the map
		if !o.AcceptedBy.Valid {
			continue
		}

		householdInvitationByKey[o.AcceptedBy.V] = append(householdInvitationByKey[o.AcceptedBy.V], o)
	}

	for _, rel := range members {

		owners, ok := householdInvitationByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.AcceptedByMember != nil {
				continue
			}

			rel.R.AcceptedByHouseholdInvitations = append(rel.R.AcceptedByHouseholdInvitations, o)

			o.R.AcceptedByMember = rel

		}
	}

	return nil
}

