type householdInvitationJoins[Q dialect.Joinable] struct {
	typ              string
	AcceptedByMember modAs[Q, memberColumns]
	CreatedByMember  modAs[Q, memberColumns]
	Household        modAs[Q, householdColumns]
}

func (j householdInvitationJoins[Q]) aliasedAs(alias string) householdInvitationJoins[Q] {
	return buildHouseholdInvitationJoins[Q](buildHouseholdInvitationColumns(alias), j.typ)
}

func buildHouseholdInvitationJoins[Q dialect.Joinable](cols householdInvitationColumns, typ string) householdInvitationJoins[Q] {
	return householdInvitationJoins[Q]{
		typ: typ,
		AcceptedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.AcceptedBy),
					))
				}

				return mods
			},
		},
		CreatedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.CreatedBy),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
	}
}
